import type { FormSettings, PageNode } from '@lowcode/schema'

/**
 * 参考 `variant-form` 的 8 个表单模板。
 *
 * 数据从参考实现的 8 个表单模板 JSON（`form-samples/json1..json8.txt`）转换而来：
 * - `defaultValue` → `modelValue`，`labelAlign` 归一为 left/center/right；
 * - `optionItems` 原样保留；
 * - 参考的 `cols` / `tabs` / `rows` 嵌套对象转换为本平台的扁平 `nodes` +
 *   `children`（grid-col / tab-pane / table-row / table-cell）。
 *
 * 参考模板里的 `sub-form` 在本平台没有对应物料，主从模板改用「表头 + 明细行」的
 * 布局表格表达；固定表格模板用 table-row / table-cell 重建为可编辑简历表。
 */
export interface FormTemplatePreset {
  id: string
  name: string
  description: string
  tags: string[]
  /** 表单级排版设置（标签位置 / 宽度 / 对齐） */
  form: Partial<FormSettings>
  /** 表单自定义 CSS（固定表格模板的紧凑行距） */
  cssCode?: string
  nodes: PageNode[]
}

